	public PrivacyNotice removeFromProcessingActivities( UUID parentId, DataProcessingActivity removeFrom ) {
	    LOGGER.info("handling RemoveProcessingActivitiesFromPrivacyNoticeEvent " );
	
	    PrivacyNotice parentEntity = repository.findById(parentId).get();
	    DataProcessingActivity child = registry.project( DataProcessingActivity.class, removeFrom.getDataProcessingActivityId());
	    
	    parentEntity.getProcessingActivities().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}

